import { supabase } from './supabase';
import type { DailyFighter } from './dailyFightBracket';

export type { DailyBout, DailyFighter } from './dailyFightBracket';
export { ROUND_NAMES, bracketFor, isBye, roundTitle } from './dailyFightBracket';

/**
 * The app's nightly 16-song fight, as published by phones during the fight
 * window. Likes decide every bout and a tie goes to the better seed.
 * The draw pairs every song that has an opponent, so a short card does
 * not hand a bye to a song that could have fought.
 */

export interface DailyFightCard {
  day: string;
  genre: string;
  fighters: DailyFighter[];
  updatedAt: string;
}

/** Tonight's card, or last night's until a new one is published. */
export async function fetchDailyFight(day?: string): Promise<DailyFightCard | null> {
  const { data, error } = await supabase.rpc('get_daily_fight', { p_day: day ?? null });
  if (error) throw new Error(error.message);
  return (data as DailyFightCard | null) ?? null;
}
