/**
 * The nightly draw. Kept free of the network client so the pairing can be
 * tested on its own.
 */

export interface DailyFighter {
  seed: number;
  title: string;
  artist: string;
  by: string;
  likes: number;
  artworkUrl: string | null;
  previewUrl: string | null;
}

export interface DailyBout {
  round: number;
  index: number;
  red: DailyFighter | null;
  blue: DailyFighter | null;
  winner: DailyFighter | null;
}

export const ROUND_NAMES = ['Round of 16', 'Quarterfinals', 'Semifinals', 'Championship'];

function winnerOf(red: DailyFighter | null, blue: DailyFighter | null): DailyFighter | null {
  if (!red) return blue;
  if (!blue) return red;
  if (red.likes !== blue.likes) return red.likes > blue.likes ? red : blue;
  return red.seed < blue.seed ? red : blue;
}

/**
 * Name a round from how close it is to the final. A short card is not a
 * round of 16, so the old fixed labels were wrong as soon as songs were missing.
 */
export function roundTitle(index: number, total: number): string {
  const fromEnd = total - 1 - index;
  if (fromEnd <= 0) return 'Championship';
  if (fromEnd === 1) return 'Semifinals';
  if (fromEnd === 2) return 'Quarterfinals';
  return `Round ${index + 1}`;
}

/**
 * Pair everyone who can be paired.
 *
 * A fixed 16-slot draw left a song on a bye whenever its opposite seed was
 * missing, even when another song was sitting on a bye of its own. Those two
 * should fight. An even field has no byes. An odd field has one, and it goes
 * to the best seed. Seeds 1 and 2 still only meet in the final if they keep
 * winning: each round pairs the top of the remaining draw with the bottom.
 */
export function bracketFor(fighters: DailyFighter[]): DailyBout[][] {
  let current: DailyFighter[] = [...fighters].sort((a, b) => a.seed - b.seed);
  if (current.length < 2) return [];
  const rounds: DailyBout[][] = [];
  while (current.length > 1) {
    const r = rounds.length;
    const seated = current.length % 2 === 1 ? current.slice(1) : current;
    const bye = current.length % 2 === 1 ? current[0] : null;
    const bouts: DailyBout[] = [];
    if (bye) {
      bouts.push({ round: r, index: 0, red: bye, blue: null, winner: bye });
    }
    const half = seated.length / 2;
    for (let i = 0; i < half; i++) {
      const red = seated[i];
      const blue = seated[seated.length - 1 - i];
      bouts.push({
        round: r,
        index: bouts.length,
        red,
        blue,
        winner: winnerOf(red, blue),
      });
    }
    rounds.push(bouts);
    current = bouts.map((b) => b.winner).filter((f): f is DailyFighter => f !== null);
  }
  return rounds;
}

export const isBye = (bout: DailyBout) => !bout.red || !bout.blue;
